from ce_common import *
dom('ce-quant')
topic('Percentages')
E('b',"A shirt priced at 800 rupees is sold at a 15% discount. What is the selling price in rupees?","680","120","700","640","Discount = 15% of 800 = 120, so the selling price is 800 − 120 = 680.","800*0.85")
E('b',"What is 20% of 250?","50","40","25","45","20% = 1/5, and 250 ÷ 5 = 50.","250*0.2")
E('b',"Three-fourths of a number is 45. What is the number?","60","34","75","90","If 3/4 of x is 45, then x = 45 × 4/3 = 60.","45*4/3")
E('i',"The price of a laptop is first raised by 25% and then reduced by 20%. What is the net change in price?","No change","5% increase","5% decrease","Increase of 20%","1.25 × 0.80 = 1.00, so the price returns to the original value.","1.25*0.8",ans=1)
E('i',"A population of 20,000 grows by 10% every year. What will it be after 2 years?","24,200","24,000","22,000","24,400","20,000 × 1.1 × 1.1 = 24,200. Growth compounds on the new value each year.","20000*1.1*1.1")
E('i',"Sales in four quarters were 120, 150, 90 and 140 units. What percentage of the yearly total was sold in the fourth quarter?","28%","25%","30%","26%","Total = 500, and 140 ÷ 500 = 28%.","140/500*100")
topic('Profit, Loss & Discount')
E('b',"An article bought for 250 rupees is sold for 300 rupees. What is the profit percentage?","20%","25%","50%","16%","Profit = 50, and profit % = 50/250 × 100 = 20%.","(300-250)/250*100")
E('i',"A shopkeeper gives successive discounts of 20% and 10% on an item marked at 1,000 rupees. What does the customer pay in rupees?","720","700","730","770","After 20%: 800. After a further 10% of 800: 720. Discounts multiply (0.8 × 0.9), they do not add.","1000*0.8*0.9")
E('i',"The cost price of 15 articles equals the selling price of 12 articles. What is the profit percentage?","25%","20%","30%","12.5%","Each article sells for 15/12 = 1.25 times its cost, a 25% profit.","(15/12-1)*100")
E('a',"A shopkeeper marks an item 40% above its cost price and then allows a 25% discount. What is his profit percentage?","5%","15%","10%","0%","Selling price = 1.40 × 0.75 = 1.05 of the cost, so the profit is 5%.","(1.4*0.75-1)*100")
topic('Ratio, Proportion & Mixtures')
E('b',"The ratio of boys to girls in a class of 40 is 3:5. How many girls are there?","25","15","20","24","The parts add up to 8, so each part is 5 students and girls = 5 × 5 = 25.","40*5/8")
E('i',"A 40-litre mixture of milk and water is in the ratio 3:1. How many litres of water must be added to make the ratio 3:2?","10","5","15","20","Milk = 30 L and water = 10 L. For 3:2 water must be 20 L, so add 10 L.","30*2/3-10")
E('i',"If 40% of A equals 25% of B, what is the ratio A:B?","5:8","8:5","2:5","4:5","0.40A = 0.25B gives A/B = 25/40 = 5/8.","25/40")
E('b',"If 6 pencils cost 42 rupees, what do 15 pencils cost in rupees?","105","90","84","120","One pencil costs 7 rupees, and 15 × 7 = 105.","42/6*15")
topic('Time, Speed & Distance')
E('b',"A car travels 150 km in 2.5 hours. What is its average speed in km/h?","60","65","55","375","Speed = distance ÷ time = 150 ÷ 2.5 = 60 km/h.","150/2.5")
E('b',"Convert a speed of 72 km/h into metres per second.","20","25","15","72","Multiply by 5/18: 72 × 5/18 = 20 m/s.","72*5/18")
E('i',"Two trains of lengths 150 m and 100 m run in opposite directions at 54 km/h and 36 km/h. How many seconds do they take to cross each other?","10","12","8","15","Relative speed = 90 km/h = 25 m/s. Total length 250 m, so time = 250/25 = 10 s.","250/((54+36)*5/18)")
E('i',"A boat moves at 15 km/h in still water and the stream flows at 3 km/h. How many hours does it need to go 72 km downstream?","4","4.8","6","5","Downstream speed = 15 + 3 = 18 km/h, so time = 72/18 = 4 hours.","72/(15+3)")
E('i',"A man walking at 5 km/h reaches his office 12 minutes late. Walking at 6 km/h he is 10 minutes early. How far is the office in km?","11","10","12","9","d/5 − d/6 = 22/60 hour, which gives d = 11 km.","(22/60)/(1/5-1/6)")
E('a',"A car covers the first half of a journey at 40 km/h and the second half at 60 km/h. What is its average speed for the whole journey in km/h?","48","50","52","45","For equal distances the average speed is the harmonic mean: 2×40×60/(40+60) = 48.","2*40*60/(40+60)")
topic('Time & Work')
E('b',"5 workers build a wall in 12 days. How many days would 10 workers take, working at the same rate?","6","24","12","8","Total work = 5 × 12 = 60 worker-days, so 10 workers need 6 days.","5*12/10")
E('i',"A can finish a job in 12 days and B in 18 days. How many days do they take working together?","7.2","15","6","7.5","Combined rate = 1/12 + 1/18 = 5/36 per day, so the job takes 36/5 = 7.2 days.","1/(1/12+1/18)")
E('a',"Two pipes fill a tank in 20 and 30 minutes. A third pipe empties it in 60 minutes. If all three are open, how many minutes does it take to fill the tank?","15","12","10","18","Net rate = 1/20 + 1/30 − 1/60 = 4/60, so the tank fills in 15 minutes.","1/(1/20+1/30-1/60)")
E('a',"A can do a piece of work in 10 days and B in 15 days. They work together for 4 days and then A leaves. How many more days will B need to finish the work?","5","6","7.5","4","In 4 days they finish 4 × (1/10 + 1/15) = 2/3. The remaining 1/3 at B's rate of 1/15 per day takes 5 days.","(1-4*(1/10+1/15))/(1/15)")
E('i',"A can finish a job in 6 days and B in 3 days. They work on alternate days, starting with A. In how many days is the job finished?","4","3","4.5","5","A does 1/6 and B does 1/3 in two days (half the job). Four days finish the whole job exactly.","4*(1/6+1/3)/2",ans=1)
topic('Interest')
E('b',"What is the simple interest on 5,000 rupees at 8% per year for 3 years?","1,200","400","1,500","1,000","SI = P × R × T / 100 = 5000 × 8 × 3 / 100 = 1,200.","5000*8*3/100")
E('i',"What is the compound interest on 10,000 rupees at 10% per year for 2 years, compounded annually?","2,100","2,000","2,200","2,310","Amount = 10,000 × 1.1² = 12,100, so the interest is 2,100.","10000*(1.1**2-1)")
E('i',"A sum becomes three times itself in 5 years at simple interest. In how many years will it become six times itself?","12.5","10","15","25","Tripling means interest = 2P in 5 years (0.4P per year). To reach 6P we need 5P of interest, which takes 12.5 years.","5*5/2")
E('a',"What is the difference between the compound interest and the simple interest on 8,000 rupees at 5% per year for 2 years?","20","40","10","200","For two years the difference is P(r/100)² = 8000 × 0.0025 = 20.","8000*0.05**2")
topic('Averages & Numbers')
E('b',"What is the average of 12, 18, 24, 30 and 36?","24","25","22","26","The sum is 120 and 120 ÷ 5 = 24.","(12+18+24+30+36)/5")
E('i',"The average of 5 numbers is 26. When one of them, 30, is removed, what is the average of the remaining four?","25","24","26","27","Total = 130. Remaining total = 100, and 100 ÷ 4 = 25.","(5*26-30)/4")
E('i',"The sum of two numbers is 45 and their difference is 9. What is the larger number?","27","36","18","24","The larger number = (45 + 9)/2 = 27.","(45+9)/2")
E('b',"What is the sum of the first 10 natural numbers?","55","45","50","66","1 + 2 + … + 10 = 10 × 11 / 2 = 55.","sum(range(1,11))")
E('b',"What is the value of √144 + ∛27?","15","21","39","12","√144 = 12 and ∛27 = 3, so the total is 15.","144**0.5+27**(1/3)")
E('b',"If x + 7 = 19, what is the value of 3x?","36","12","57","19","x = 12, so 3x = 36.","3*(19-7)")
topic('Number System')
E('b',"What is the LCM of 12 and 18?","36","6","72","216","12 = 2² × 3 and 18 = 2 × 3². The LCM takes the highest powers: 2² × 3² = 36.","12*18//math.gcd(12,18)")
E('b',"What is the HCF of 36 and 60?","12","6","18","24","36 = 2² × 3² and 60 = 2² × 3 × 5. The common part is 2² × 3 = 12.","math.gcd(36,60)")
E('b',"What is the smallest prime number greater than 50?","53","51","57","59","51 = 3 × 17 and 52 is even, so the next prime is 53.","next(n for n in range(51,100) if all(n%i for i in range(2,n)))")
E('i',"How many three-digit numbers are divisible by 7?","128","129","127","130","The smallest is 105 and the largest is 994, giving (994 − 105)/7 + 1 = 128.","sum(1 for n in range(100,1000) if n%7==0)")
E('i',"How many zeros are at the end of 25! (25 factorial)?","6","5","7","4","Count the factors of 5: 25/5 = 5 and 25/25 = 1, so 5 + 1 = 6 trailing zeros.","25//5+25//25")
E('a',"What is the last digit of 7 raised to the power 2026?","9","7","3","1","The last digits of powers of 7 repeat as 7, 9, 3, 1. Since 2026 mod 4 = 2, the digit is 9.","pow(7,2026,10)")
E('a',"What is the remainder when 2 raised to the power 50 is divided by 7?","4","1","2","6","2³ = 8 leaves remainder 1, so powers cycle with period 3. 50 mod 3 = 2, giving 2² = 4.","pow(2,50,7)")
E('a',"How many positive divisors does 360 have?","24","18","30","20","360 = 2³ × 3² × 5, so the count is (3+1)(2+1)(1+1) = 24.","sum(1 for i in range(1,361) if 360%i==0)")
E('a',"If the roots of x² − 7x + k = 0 differ by 3, what is k?","10","12","14","8","The roots are 5 and 2 (sum 7, difference 3), so k = 5 × 2 = 10.","((7+3)/2)*((7-3)/2)")
E('a',"If log base 2 of x plus log base 2 of (x − 2) equals 3, what is x?","4","2","6","−2","x(x − 2) = 8 gives x² − 2x − 8 = 0, so x = 4 or −2. Only x = 4 keeps both logarithms defined.","math.log2(4)+math.log2(4-2)",ans=3)
topic('Geometry & Mensuration')
E('b',"A rectangle is 14 cm long and 9 cm wide. What is its area in square centimetres?","126","46","23","252","Area = length × width = 14 × 9 = 126.","14*9")
E('b',"The area of a square is 81 square metres. What is its perimeter in metres?","36","18","27","81","The side is 9 m, so the perimeter is 4 × 9 = 36 m.","4*81**0.5")
E('i',"How many diagonals does a hexagon have?","9","6","12","15","A polygon with n sides has n(n − 3)/2 diagonals: 6 × 3 / 2 = 9.","6*3/2")
E('i',"What is the sum of the interior angles of a pentagon, in degrees?","540","360","720","450","The sum is (n − 2) × 180 = 3 × 180 = 540.","(5-2)*180")
E('i',"What is the angle between the hands of a clock at 3:30?","75°","90°","60°","105°","The hour hand is at 105° and the minute hand at 180°, so the angle is 75°.","abs(0.5*(3*60+30)-6*30)")
E('a',"The radius of a cylinder is doubled and its height is halved. What happens to its volume?","It doubles","It stays the same","It halves","It becomes four times","Volume ∝ r² × h, so the factor is 2² × 1/2 = 2.","2**2*0.5",ans=2)
E('a',"How many squares of all sizes are there on a 4 × 4 grid of unit squares?","30","16","25","20","1² + 2² + 3² + 4² = 1 + 4 + 9 + 16 = 30.","sum(k*k for k in range(1,5))")
topic('Permutations, Combinations & Probability')
E('i',"In how many distinct ways can the letters of the word LEVEL be arranged?","30","60","120","15","5 letters with L repeated twice and E repeated twice: 5!/(2! × 2!) = 30.","math.factorial(5)/(2*2)")
E('i',"Two fair dice are rolled. What is the probability that the sum is 8?","5/36","1/6","7/36","1/9","The pairs (2,6), (3,5), (4,4), (5,3), (6,2) give 5 favourable outcomes out of 36.","5/36")
E('a',"A committee of 3 is chosen from 5 men and 4 women. In how many ways can it include at least one woman?","74","84","64","80","Total C(9,3) = 84. Committees with no woman = C(5,3) = 10. So 84 − 10 = 74.","comb(9,3)-comb(5,3)")
E('a',"One card is drawn from a standard 52-card deck. What is the probability that it is a king or a heart?","4/13","17/52","5/13","3/13","There are 13 hearts plus 3 other kings = 16 cards, and 16/52 = 4/13. The king of hearts must not be counted twice.","16/52")
E('a',"A bag has 4 red and 5 blue balls. Two balls are drawn without replacement. What is the probability that both have the same colour?","4/9","1/2","5/9","41/81","(C(4,2) + C(5,2)) / C(9,2) = 16/36 = 4/9. The figure 41/81 would be the answer with replacement.","(comb(4,2)+comb(5,2))/comb(9,2)")
E('a',"In how many ways can 6 people sit around a circular table?","120","720","24","60","For circular arrangements fix one person and arrange the others: (6 − 1)! = 120.","math.factorial(5)")
topic('Series & Ages')
E('i',"A father is three times as old as his son. After 12 years he will be twice as old as the son. What is the son's present age in years?","12","10","8","15","3s + 12 = 2(s + 12) gives s = 12. Check: father 36, son 12; in 12 years 48 and 24.","3*12+12-2*(12+12)",ans=0)
E('a',"What is the sum of the first 6 terms of the series 2 + 6 + 18 + …?","728","729","486","1,456","This is a geometric series with ratio 3: 2(3⁶ − 1)/(3 − 1) = 728.","2*(3**6-1)/(3-1)")
topic('Averages & Numbers')
E('b',"What is 0.375 written as a fraction in simplest form?","3/8","3/5","5/8","1/3","0.375 = 375/1000 = 3/8.","3/8")
topic('Ratio, Proportion & Mixtures')
E('a',"Aman invests 6,000 rupees for 12 months and Bharat invests 8,000 rupees for 6 months. They share a profit of 3,000 rupees. How much does Aman get in rupees?","1,800","1,500","2,000","1,200","Capital × time: 72,000 : 48,000 = 3 : 2. Aman gets 3/5 of 3,000 = 1,800.","3000*72000/(72000+48000)")
topic('Interest')
E('i',"A sum of money doubles itself in 8 years at simple interest. What is the annual rate of interest?","12.5%","10%","8%","15%","Interest equals the principal in 8 years, so rate = 100/8 = 12.5% per year.","100/8")
topic('Permutations, Combinations & Probability')
E('a',"A bag holds 3 red and 2 blue balls. One red ball is drawn and not replaced. What is the probability the next ball is red?","1/2","3/5","2/5","3/4","After one red is removed there are 2 red among 4 balls, so the probability is 2/4 = 1/2.","2/4")
topic('Number System')
E('i',"What is the smallest number that leaves a remainder of 3 when divided by 4, 5 or 6?","63","123","23","183","The LCM of 4, 5 and 6 is 60, so the number is 60 + 3 = 63.","60+3")
topic('Time, Speed & Distance')
E('b',"How many minutes are there in 2.5 hours?","150","125","250","120","2.5 × 60 = 150.","2.5*60")
E('i',"A train 200 m long passes a pole in 10 seconds. What is its speed in km/h?","72","20","60","80","Speed = 200/10 = 20 m/s = 20 × 18/5 = 72 km/h.","200/10*18/5")
topic('Series & Ages')
E('a',"What is the value of 1/2 + 1/6 + 1/12 + 1/20 + 1/30?","5/6","1","3/4","4/5","Each term is 1/(n(n+1)) = 1/n − 1/(n+1), so the sum telescopes to 1 − 1/6 = 5/6.","1-1/6")
topic('Interest')
E('i',"What is the compound interest rate that makes a sum double in exactly 2 years? (Choose the nearest value.)","41.4%","50%","100%","25%","(1 + r)² = 2 gives r = √2 − 1 ≈ 41.4%.","round((2**0.5-1)*100,1)")

topic('Percentages')
E('b',"Which is greater: 40% of 50 or 50% of 38?","40% of 50","50% of 38","They are equal","Cannot be determined","40% of 50 = 20 and 50% of 38 = 19.","0.4*50>0.5*38",ans=1)
